<?php
include_once MODEL . 'PayoutTransaction.php';
$model = ohnous_table_exists('payout_transactions') ? new PayoutTransaction($bdd) : null;
$row = $model ? $model->findById((int)($_GET['id']??0)) : null;
if(!$row){http_response_code(404);echo '<main class="admin-shell"><p>PayOut introuvable.</p></main>';return;}
$history = $model->getStatusHistory((int)$row['id']);
$debugEnabled = !empty((include CONFIG . 'payment.php')['freshpay']['payout']['debug']);
$statusDebug = null;$callbackReceived = null;$callbackDecrypted = null;
foreach($history as $event){$eventPayload=json_decode((string)($event['payload']??''),true);if($event['source']==='status_api'&&is_array($eventPayload)){$statusDebug=$eventPayload;}if($event['source']==='callback'&&is_array($eventPayload)){$callbackReceived=$eventPayload['received']??null;$callbackDecrypted=$eventPayload['decrypted']??null;}}
$labels=['pending'=>'En attente','submitted'=>'Soumis','processing'=>'En attente','success'=>'Réussi','successful'=>'Réussi','paid'=>'Réussi','completed'=>'Réussi','failed'=>'Échoué','error'=>'Échoué','expired'=>'Expiré','cancelled'=>'Annulé','canceled'=>'Annulé'];
$operators=['airtel'=>'Airtel Money','orange'=>'Orange Money','mpesa'=>'M-Pesa','afrimoney'=>'Afrimoney'];
$status=strtolower((string)$row['status']);$label=$labels[$status]??ucfirst($status);
$chartLabels=[];$chartValues=[];foreach($history as $index=>$event){$chartLabels[]=date('d/m H:i',strtotime($event['created_at']));$chartValues[]=$index+1;}
if(!$history){$chartLabels=[date('d/m H:i',strtotime($row['created_at']))];$chartValues=[1];}
?>
