<section class="admin-detail-card"><h2>Références FreshPay</h2><dl class="admin-detail-list"><div><dt>Référence interne</dt><dd><?= htmlspecialchars($row['reference'],ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Référence FreshPay</dt><dd><?= htmlspecialchars($row['freshpay_reference']?:'—',ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Référence opérateur</dt><dd><?= htmlspecialchars($row['operator_reference']?:'—',ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>ID transaction</dt><dd><?= htmlspecialchars($row['transaction_id']?:'—',ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Message</dt><dd><?= htmlspecialchars($row['status_description']?:'—',ENT_QUOTES,'UTF-8') ?></dd></div><div><dt>Erreur détaillée</dt><dd><?= htmlspecialchars($row['error_detail']?:'—',ENT_QUOTES,'UTF-8') ?></dd></div></dl><button class="btn_ohnous" id="payout_refresh" data-reference="<?= htmlspecialchars($row['reference'],ENT_QUOTES,'UTF-8') ?>"><i class="fa-solid fa-rotate"></i> Actualiser</button></section>
<section class="admin-detail-card admin-detail-card--wide"><h2>Évolution de la transaction</h2><div id="payout_status_chart" class="admin-chart"></div><ol class="transaction-timeline"><?php foreach($history as $event): ?><li><span><strong><?= htmlspecialchars($labels[strtolower($event['status'])]??ucfirst($event['status']),ENT_QUOTES,'UTF-8') ?></strong><br><?= htmlspecialchars($event['description']?:'—',ENT_QUOTES,'UTF-8') ?> <small>(<?= htmlspecialchars($event['source'],ENT_QUOTES,'UTF-8') ?>)</small></span><span><?= htmlspecialchars($event['created_at'],ENT_QUOTES,'UTF-8') ?></span></li><?php endforeach ?></ol></section>
<section class="admin-detail-card admin-detail-card--wide"><h2>Réponse FreshPay</h2><pre class="payout-json"><?= htmlspecialchars(json_encode(json_decode((string)$row['response_payload'],true) ?: $row['response_payload'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),ENT_QUOTES,'UTF-8') ?></pre></section>
<section class="admin-detail-card admin-detail-card--wide"><h2>Échanges FreshPay complets</h2><?php foreach($history as $event): $payload=json_decode((string)($event['payload']??''),true); if(!$payload) continue; ?><h3><?= htmlspecialchars($event['source'].' — '.$event['created_at'],ENT_QUOTES,'UTF-8') ?></h3><pre class="payout-json"><?= htmlspecialchars(json_encode($payload,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),ENT_QUOTES,'UTF-8') ?></pre><?php endforeach ?></section>
<?php if($debugEnabled): ?><section class="admin-detail-card admin-detail-card--wide"><h2>Débogage FreshPay</h2><h3>Requête PayOut</h3><pre class="payout-json"><?= htmlspecialchars(json_encode(json_decode((string)$row['request_payload'],true) ?: $row['request_payload'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),ENT_QUOTES,'UTF-8') ?></pre><h3>Requête et réponse Check Status</h3><pre class="payout-json"><?= htmlspecialchars(json_encode($statusDebug,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),ENT_QUOTES,'UTF-8') ?></pre><h3>Callback reçu</h3><pre class="payout-json"><?= htmlspecialchars(json_encode($callbackReceived,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),ENT_QUOTES,'UTF-8') ?></pre><h3>Callback déchiffré</h3><pre class="payout-json"><?= htmlspecialchars(json_encode($callbackDecrypted,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),ENT_QUOTES,'UTF-8') ?></pre></section><?php endif ?></div></main>
